#!/usr/bin/env python3
"""Stage an Arduino library locally, without uploading, tagging or git operations.

The destination must not exist. Compile against the resulting directory before
hardware qualification; publish only after the exact candidate passes on motors.
"""
import argparse
from pathlib import Path
import re
import shutil
import zipfile

CORE_FILES = (
    'Servomotor.cpp', 'Servomotor.h', 'Commands.h', 'Communication.cpp',
    'Communication.h', 'DataTypes.cpp', 'DataTypes.h', 'Utils.h',
    'AutoGeneratedUnitConversions.cpp', 'AutoGeneratedUnitConversions.h',
    'library.properties', 'README.md', 'keywords.txt', 'LICENSE', 'CHANGELOG.md',
)


def stage(destination, source=None):
    source = Path(source) if source else Path(__file__).resolve().parent
    destination = Path(destination)
    missing = [name for name in CORE_FILES if not (source / name).is_file()]
    if missing:
        raise FileNotFoundError('Required library files missing: ' + ', '.join(missing))
    properties = (source / 'library.properties').read_text()
    if not re.search(r'^version=\d+\.\d+\.\d+$', properties, re.M):
        raise ValueError('library.properties must have a three-part version')
    destination.mkdir(parents=True, exist_ok=False)
    (destination / 'src').mkdir()
    for name in CORE_FILES:
        path = source / name
        if path.suffix in ('.cpp', '.h'):
            shutil.copy2(path, destination / 'src' / name)
            if path.suffix == '.h':
                shutil.copy2(path, destination / name)
        else:
            shutil.copy2(path, destination / name)
    for path in sorted(source.glob('example_*.cpp')):
        name = path.stem[len('example_'):].title()
        example = destination / 'examples' / name
        example.mkdir(parents=True)
        shutil.copy2(path, example / (name + '.ino'))
    return destination


def archive(directory):
    """Deterministic ZIP for recording the exact candidate before qualification."""
    directory = Path(directory)
    path = directory.parent / (directory.name + '.zip')
    with zipfile.ZipFile(path, 'x', compression=zipfile.ZIP_DEFLATED) as output:
        for file in sorted(directory.rglob('*')):
            if file.is_file():
                entry = zipfile.ZipInfo((Path(directory.name) / file.relative_to(directory)).as_posix(), (2026, 1, 1, 0, 0, 0))
                entry.compress_type = zipfile.ZIP_DEFLATED
                entry.external_attr = 0o100644 << 16
                output.writestr(entry, file.read_bytes())
    return path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('destination', type=Path)
    parser.add_argument('--zip', action='store_true')
    args = parser.parse_args()
    staged = stage(args.destination)
    print(archive(staged) if args.zip else staged)


if __name__ == '__main__':
    main()
